# SPDX-License-Identifier: MIT
# An FTP server in MicroPython, polled from the GUI's timer: it never blocks the screen. Commands
# are answered at once; files move in pieces, a few milliseconds of each tick, so the screen keeps
# its pace while a PC copies gigabytes.
#
#   server = Server(root="/", user="mpy", password="123456", port=21, note=print)
#   server.start()
#   server.poll(budget_ms=10)     # from a timer, every 20 ms
#   server.stop()
#
# Passive (PASV, EPSV) and active (PORT, EPRT) data connections, so every client works: FileZilla,
# WinSCP, Windows Explorer, the file managers of Linux and macOS, curl, lftp, ftp. Listings in
# both forms (LIST like ls -l, MLSD with exact times), resume (REST), rename, delete, folders.
#
# Plain FTP: the password and the files cross the network in clear. Use it on your own network.

import errno
import os
import socket
import time

try:
    import select
except ImportError:
    select = None

MONTHS = ("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")
PASSIVE_PORTS = range(50000, 50100)
CHUNK = 32768
IDLE_SECONDS = 600
MAX_SESSIONS = 8
WRONG_PASSWORDS = 3

S_IFMT, S_IFDIR, S_IFLNK = 0o170000, 0o040000, 0o120000
_AGAIN = (errno.EAGAIN, getattr(errno, "EWOULDBLOCK", errno.EAGAIN))


def local_addresses():
    """The board's IPv4 addresses, without 127.x, read from /proc (no subprocess)."""
    found = []
    try:
        with open("/proc/net/fib_trie") as source:
            last = None
            for line in source:
                line = line.strip()
                if line.startswith("|--"):
                    last = line[3:].strip()
                elif line.startswith("/32 host LOCAL") and last and not last.startswith("127."):
                    if last not in found:
                        found.append(last)
    except OSError:
        pass
    return found


def _ip_value(ip):
    try:
        a, b, c, d = (int(x) for x in ip.split("."))
        return (a << 24) | (b << 16) | (c << 8) | d
    except ValueError:
        return 0


def _closest(addresses, peer):
    # The address of the network the client came from: the one with the longest common prefix.
    best, best_bits = (addresses[0] if addresses else "127.0.0.1"), -1
    p = _ip_value(peer)
    for ip in addresses:
        x = _ip_value(ip) ^ p
        bits = 32
        while x:
            x >>= 1
            bits -= 1
        if bits > best_bits:
            best, best_bits = ip, bits
    return best


def _peer_ip(address):
    if isinstance(address, tuple):
        return address[0]
    if len(address) >= 8:  # MicroPython: the raw sockaddr_in
        return ".".join(str(b) for b in address[4:8])
    return "?"


def _mode_text(mode):
    kind = mode & S_IFMT
    text = "d" if kind == S_IFDIR else "l" if kind == S_IFLNK else "-"
    for shift in (6, 3, 0):
        bits = (mode >> shift) & 7
        text += ("r" if bits & 4 else "-") + ("w" if bits & 2 else "-") + ("x" if bits & 1 else "-")
    return text


def _ls_time(seconds, now):
    t = time.localtime(seconds)
    if abs(now - seconds) < 180 * 86400:
        return "%s %2d %02d:%02d" % (MONTHS[t[1] - 1], t[2], t[3], t[4])
    return "%s %2d  %4d" % (MONTHS[t[1] - 1], t[2], t[0])


def _utc_text(seconds):
    t = time.gmtime(seconds)
    return "%04d%02d%02d%02d%02d%02d" % t[:6]


def _is_dir(path):
    try:
        return os.stat(path)[0] & S_IFMT == S_IFDIR
    except OSError:
        return False


def _error_text(error):
    code = error.args[0] if error.args else 0
    return {errno.ENOENT: "No such file or folder", errno.EACCES: "Permission denied",
            errno.EPERM: "Not allowed", errno.EEXIST: "Already exists",
            errno.EISDIR: "It is a folder", 28: "The card is full",
            39: "The folder is not empty", 20: "Not a folder", 18: "Not on the same file system"}.get(code, "Error %s" % code)


class _Transfer:
    # Data for or from the client: bytes (a listing), a file to send, a file to receive.

    def __init__(self, kind, name, source=None, data=b"", target=None):
        self.kind = kind  # "list", "send", "receive"
        self.name = name
        self.source = source
        self.target = target
        self.pending = memoryview(data) if data else None
        self.bytes = 0
        self.started = time.ticks_ms()
        self.size = 0

    def close(self):
        for f in (self.source, self.target):
            if f:
                try:
                    f.close()
                except OSError:
                    pass


class Session:
    def __init__(self, server, sock, peer):
        self.server = server
        self.sock = sock
        self.peer = peer
        sock.setblocking(False)
        self.incoming = b""
        self.outgoing = b""
        self.user = None
        self.logged = False
        self.wrong = 0
        self.cwd = "/"
        self.listener = None  # passive: our listening socket
        self.active = None  # active: the client's (ip, port)
        self.data = None  # the data connection
        self.transfer = None
        self.waiting_since = 0
        self.rename_from = None
        self.rest = 0
        self.last = time.time()
        self.closed = False
        self.quitting = False
        self.reply(220, "MicroPython FTP server ready")

    # --- the control connection

    def reply(self, code, text):
        lines = text.split("\n")
        out = ""
        for line in lines[:-1]:
            out += "%d-%s\r\n" % (code, line)
        out += "%d %s\r\n" % (code, lines[-1])
        self.outgoing += out.encode()

    def poll(self):
        if self.closed:
            return False
        busy = False
        try:
            part = self.sock.recv(4096)
            if not part:
                self.close()
                return False
            self.incoming += part
            busy = True
        except OSError as error:
            if error.args[0] not in _AGAIN:
                self.close()
                return False
        while b"\n" in self.incoming and not self.closed:
            line, _, self.incoming = self.incoming.partition(b"\n")
            self.last = time.time()
            try:
                text = line.rstrip(b"\r").decode()
            except UnicodeError:
                self.reply(501, "Names must be UTF-8")
                continue
            self.command(text)
            busy = True
        if len(self.incoming) > 8192:
            self.close()
            return False
        self._flush()
        if self.quitting and not self.outgoing:
            self.close()
        elif not self.transfer and time.time() - self.last > IDLE_SECONDS:
            self.reply(421, "Idle for too long")
            self._flush()
            self.close()
        return busy

    def _flush(self):
        while self.outgoing:
            try:
                n = self.sock.send(self.outgoing)
            except OSError as error:
                if error.args[0] not in _AGAIN:
                    self.close()
                return
            if not n:
                return
            self.outgoing = self.outgoing[n:]

    def close(self):
        if self.closed:
            return
        self.closed = True
        self._end_data()
        try:
            self.sock.close()
        except OSError:
            pass
        self.server.note(self.peer, "left" if self.logged else "disconnected")

    # --- paths: what the client sees ("/music/a.mp3") and the real one (root + it)

    def virtual(self, arg):
        path = arg if arg.startswith("/") else self.cwd.rstrip("/") + "/" + arg
        parts = []
        for part in path.split("/"):
            if part in ("", "."):
                continue
            if part == "..":
                if parts:
                    parts.pop()
            else:
                parts.append(part)
        return "/" + "/".join(parts)

    def real(self, virtual):
        root = self.server.root.rstrip("/")
        return (root + virtual) if virtual != "/" else (root or "/")

    # --- commands

    def command(self, text):
        verb, _, arg = text.partition(" ")
        verb = verb.upper()
        if verb in ("XPWD", "XCWD", "XMKD", "XRMD", "XCUP"):
            verb = {"XPWD": "PWD", "XCWD": "CWD", "XMKD": "MKD", "XRMD": "RMD", "XCUP": "CDUP"}[verb]
        if not self.logged and verb not in ("USER", "PASS", "QUIT", "FEAT", "SYST", "NOOP", "AUTH", "OPTS", "HELP"):
            self.reply(530, "Log in first")
            return
        handler = getattr(self, "_" + verb, None) if verb.isalpha() else None
        if handler is None:
            self.reply(502, "%s is not implemented" % verb)
            return
        try:
            handler(arg)
        except OSError as error:
            self.reply(550, _error_text(error))
        if verb not in ("REST", "RETR", "STOR", "APPE"):
            self.rest = 0
        if verb not in ("RNFR", "RNTO"):
            self.rename_from = None

    def _USER(self, arg):
        self.user = arg
        self.logged = False
        self.reply(331, "Password, please")

    def _PASS(self, arg):
        if self.user == self.server.user and arg == self.server.password:
            self.logged = True
            self.reply(230, "Welcome")
            self.server.note(self.peer, "logged in")
            return
        self.wrong += 1
        self.server.note(self.peer, "wrong password")
        self.reply(530, "Wrong user or password")
        if self.wrong >= WRONG_PASSWORDS:
            self.quitting = True

    def _QUIT(self, arg):
        self.reply(221, "Goodbye")
        self.quitting = True

    def _AUTH(self, arg):
        self.reply(502, "No TLS: plain FTP")

    def _SYST(self, arg):
        self.reply(215, "UNIX Type: L8")

    def _NOOP(self, arg):
        self.reply(200, "OK")

    def _HELP(self, arg):
        self.reply(214, "Standard commands, and MLSD, MLST, SIZE, MDTM, REST, EPSV, EPRT")

    def _FEAT(self, arg):
        self.reply(211, "Features:\n EPRT\n EPSV\n MDTM\n MLST type*;size*;modify*;perm*;\n"
                        " PASV\n REST STREAM\n SIZE\n UTF8\nEnd")

    def _OPTS(self, arg):
        if arg.upper().startswith("UTF8"):
            self.reply(200, "UTF-8 always")
        elif arg.upper().startswith("MLST"):
            self.reply(200, "MLST OPTS type;size;modify;perm;")
        else:
            self.reply(501, "Unknown option")

    def _TYPE(self, arg):
        self.reply(200, "Type %s (files go as they are)" % (arg.upper() or "I"))

    def _MODE(self, arg):
        self.reply(200 if arg.upper() == "S" else 504, "Mode S")

    def _STRU(self, arg):
        self.reply(200 if arg.upper() == "F" else 504, "Structure F")

    def _ALLO(self, arg):
        self.reply(202, "No need")

    def _PWD(self, arg):
        self.reply(257, '"%s" is the current folder' % self.cwd.replace('"', '""'))

    def _CWD(self, arg):
        target = self.virtual(arg or "/")
        if _is_dir(self.real(target)):
            self.cwd = target
            self.reply(250, "Now in %s" % target)
        else:
            self.reply(550, "No such folder")

    def _CDUP(self, arg):
        self._CWD("..")

    def _MKD(self, arg):
        target = self.virtual(arg)
        os.mkdir(self.real(target))
        self.server.note(self.peer, "new folder " + target)
        self.reply(257, '"%s" created' % target.replace('"', '""'))

    def _RMD(self, arg):
        target = self.virtual(arg)
        if target == "/":
            self.reply(550, "Not the top folder")
            return
        os.rmdir(self.real(target))
        self.server.note(self.peer, "removed " + target)
        self.reply(250, "Folder removed")

    def _DELE(self, arg):
        target = self.virtual(arg)
        os.remove(self.real(target))
        self.server.note(self.peer, "deleted " + target)
        self.reply(250, "Deleted")

    def _RNFR(self, arg):
        target = self.virtual(arg)
        os.stat(self.real(target))
        self.rename_from = target
        self.reply(350, "And the new name?")

    def _RNTO(self, arg):
        if not self.rename_from:
            self.reply(503, "RNFR first")
            return
        target = self.virtual(arg)
        os.rename(self.real(self.rename_from), self.real(target))
        self.server.note(self.peer, "renamed %s to %s" % (self.rename_from, target))
        self.rename_from = None
        self.reply(250, "Renamed")

    def _SIZE(self, arg):
        st = os.stat(self.real(self.virtual(arg)))
        if st[0] & S_IFMT == S_IFDIR:
            self.reply(550, "It is a folder")
        else:
            self.reply(213, str(st[6]))

    def _MDTM(self, arg):
        st = os.stat(self.real(self.virtual(arg)))
        self.reply(213, _utc_text(st[8]))

    def _REST(self, arg):
        try:
            self.rest = max(0, int(arg))
        except ValueError:
            self.reply(501, "A number, please")
            return
        self.reply(350, "From byte %d" % self.rest)

    def _ABOR(self, arg):
        if self.transfer:
            self._end_data()
            self.reply(426, "Transfer stopped")
        self.reply(226, "Nothing running")

    # --- data connections

    def _PASV(self, arg):
        self._open_listener()
        if not self.listener:
            return
        ip = _closest(self.server.addresses(), self.peer).replace(".", ",")
        port = self.listener_port
        self.reply(227, "Entering Passive Mode (%s,%d,%d)" % (ip, port >> 8, port & 255))

    def _EPSV(self, arg):
        if arg.upper() == "ALL":
            self.reply(200, "EPSV only")
            return
        self._open_listener()
        if self.listener:
            self.reply(229, "Entering Extended Passive Mode (|||%d|)" % self.listener_port)

    def _PORT(self, arg):
        try:
            n = [int(x) for x in arg.split(",")]
            ip, port = "%d.%d.%d.%d" % tuple(n[:4]), n[4] * 256 + n[5]
        except (ValueError, IndexError, TypeError):
            self.reply(501, "PORT h1,h2,h3,h4,p1,p2")
            return
        self._set_active(ip, port)

    def _EPRT(self, arg):
        parts = arg.split(arg[:1]) if arg else []
        if len(parts) < 4 or parts[1] != "1":
            self.reply(522, "IPv4 only (1)")
            return
        try:
            self._set_active(parts[2], int(parts[3]))
        except ValueError:
            self.reply(501, "EPRT |1|ip|port|")

    def _set_active(self, ip, port):
        if ip != self.peer:  # no connections to a third host (the FTP bounce)
            self.reply(504, "Only to your own address")
            return
        self._end_data()
        self.active = (ip, port)
        self.reply(200, "PORT OK")

    def _open_listener(self):
        self._end_data()
        for _ in range(len(PASSIVE_PORTS)):
            port = PASSIVE_PORTS[self.server.next_port % len(PASSIVE_PORTS)]
            self.server.next_port += 1
            listener = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            try:
                listener.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
                listener.bind(socket.getaddrinfo("0.0.0.0", port)[0][-1])
                listener.listen(1)
                listener.setblocking(False)
            except OSError:
                listener.close()
                continue
            self.listener, self.listener_port = listener, port
            return
        self.reply(425, "No free port for the data")

    def _connect_data(self):
        # True once the data connection is there (accepted, or connected to the client).
        if self.data:
            return True
        if self.listener:
            try:
                sock, address = self.listener.accept()
            except OSError:
                return False
            if _peer_ip(address) != self.peer:
                sock.close()
                return False
            self.listener.close()
            self.listener = None
            sock.setblocking(False)
            self.data = sock
            return True
        if self.active:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(3)
            try:
                sock.connect(socket.getaddrinfo(self.active[0], self.active[1])[0][-1])
            except OSError:
                sock.close()
                self.active = None
                self._fail(425, "Cannot connect to your data port")
                return False
            self.active = None
            sock.setblocking(False)
            self.data = sock
            return True
        return False

    def _start(self, transfer):
        if not (self.listener or self.active or self.data):
            transfer.close()
            self.reply(425, "PASV or PORT first")
            return
        self.transfer = transfer
        self.waiting_since = time.time()
        self.reply(150, "Here it comes" if transfer.kind != "receive" else "Send it")
        self.server.started(self)

    def _fail(self, code, text):
        self._end_data()
        self.reply(code, text)

    def _end_data(self):
        if self.transfer:
            self.transfer.close()
            self.server.finished(self, self.transfer, False)
            self.transfer = None
        for sock in (self.data, self.listener):
            if sock:
                try:
                    sock.close()
                except OSError:
                    pass
        self.data = self.listener = None
        self.active = None

    def _done(self):
        transfer = self.transfer
        self.transfer = None
        transfer.close()
        try:
            self.data.close()
        except OSError:
            pass
        self.data = None
        self.server.finished(self, transfer, True)
        self.reply(226, "Done")

    def step(self, deadline):
        # Moves the data until the deadline (ticks_ms). True when it moved something.
        transfer = self.transfer
        if not transfer or self.closed:
            return False
        if not self._connect_data():
            if self.transfer and time.time() - self.waiting_since > 20:
                self._fail(425, "No data connection")
            return False
        moved = False
        try:
            while time.ticks_diff(deadline, time.ticks_ms()) > 0:
                if transfer.kind == "receive":
                    try:
                        part = self.data.recv(CHUNK)
                    except OSError as error:
                        if error.args[0] in _AGAIN:
                            break
                        raise
                    if not part:
                        self._done()
                        break
                    transfer.target.write(part)
                    transfer.bytes += len(part)
                    moved = True
                    continue
                if transfer.pending is None or not len(transfer.pending):
                    part = transfer.source.read(CHUNK) if transfer.source else b""
                    if not part:
                        self._done()
                        break
                    transfer.pending = memoryview(part)
                try:
                    n = self.data.send(transfer.pending)
                except OSError as error:
                    if error.args[0] in _AGAIN:
                        break
                    raise
                if not n:
                    break
                transfer.pending = transfer.pending[n:]
                transfer.bytes += n
                moved = True
        except OSError as error:
            self._fail(426 if error.args[0] in (errno.ECONNRESET, 32) else 451,
                       "Transfer broken" if error.args[0] in (errno.ECONNRESET, 32) else _error_text(error))
        self._flush()
        return moved

    # --- transfers

    def _listing(self, arg, machine):
        names = [a for a in arg.split(" ") if a and not a.startswith("-")] if not machine else [arg]
        target = self.virtual(names[0] if names and names[0] else ".")
        path = self.real(target)
        st = os.stat(path)
        now = time.time()
        out = []
        if st[0] & S_IFMT == S_IFDIR:
            entries = []
            for entry in os.ilistdir(path):
                name = entry[0]
                if name in (".", ".."):
                    continue
                try:
                    entries.append((name, os.stat(path.rstrip("/") + "/" + name)))
                except OSError:
                    entries.append((name, (0o120777, 0, 0, 1, 0, 0, 0, 0, 0, 0)))
        else:
            entries = [(target.rsplit("/", 1)[-1], st)]
        entries.sort(key=lambda e: e[0])
        for name, s in entries:
            if machine:
                folder = s[0] & S_IFMT == S_IFDIR
                out.append("type=%s;size=%d;modify=%s;perm=%s; %s\r\n" % (
                    "dir" if folder else "file", s[6], _utc_text(s[8]),
                    "flcdmpe" if folder else "adfrw", name))
            else:
                out.append("%s %3d %-8s %-8s %12d %s %s\r\n" % (
                    _mode_text(s[0]), s[3], "root", "root", s[6], _ls_time(s[8], now), name))
        return "".join(out).encode()

    def _LIST(self, arg):
        self._start(_Transfer("list", "listing", data=self._listing(arg, False)))

    def _MLSD(self, arg):
        target = self.virtual(arg or ".")
        if not _is_dir(self.real(target)):
            self.reply(501, "Not a folder")
            return
        self._start(_Transfer("list", "listing", data=self._listing(arg, True)))

    def _NLST(self, arg):
        target = self.virtual(arg or ".")
        names = [e[0] for e in os.ilistdir(self.real(target)) if e[0] not in (".", "..")]
        names.sort()
        self._start(_Transfer("list", "listing", data="".join(n + "\r\n" for n in names).encode()))

    def _MLST(self, arg):
        target = self.virtual(arg or ".")
        s = os.stat(self.real(target))
        folder = s[0] & S_IFMT == S_IFDIR
        self.reply(250, "Listing %s\n type=%s;size=%d;modify=%s;perm=%s; %s\nEnd" % (
            target, "dir" if folder else "file", s[6], _utc_text(s[8]),
            "flcdmpe" if folder else "adfrw", target))

    def _RETR(self, arg):
        target = self.virtual(arg)
        path = self.real(target)
        if _is_dir(path):
            self.reply(550, "It is a folder")
            return
        source = open(path, "rb")
        if self.rest:
            source.seek(self.rest)
        transfer = _Transfer("send", target, source=source)
        transfer.size = os.stat(path)[6]
        self._start(transfer)

    def _STOR(self, arg, append=False):
        target = self.virtual(arg)
        path = self.real(target)
        if self.rest and not append:
            f = open(path, "r+b")
            f.seek(self.rest)
        else:
            f = open(path, "ab" if append else "wb")
        self._start(_Transfer("receive", target, target=f))

    def _APPE(self, arg):
        self._STOR(arg, append=True)


class Server:
    """note(who, what) tells the screen what happens."""

    def __init__(self, root="/", user="mpy", password="", port=21, note=None):
        self.root = root
        self.user = user
        self.password = password
        self.port = port
        self._note = note
        self.sessions = []
        self.next_port = 0
        self.received = 0
        self.sent = 0
        self._listener = None
        self._addresses = []
        self._addresses_at = None

    def note(self, who, what):
        if self._note:
            self._note(who, what)

    def addresses(self):
        now = time.time()
        if self._addresses_at is None or now - self._addresses_at > 10:
            self._addresses = local_addresses()
            self._addresses_at = now
        return self._addresses

    def start(self):
        if self._listener:
            return
        listener = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        try:
            listener.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            listener.bind(socket.getaddrinfo("0.0.0.0", self.port)[0][-1])
            listener.listen(4)
            listener.setblocking(False)
        except OSError:
            listener.close()
            raise
        self._listener = listener

    def stop(self):
        for session in self.sessions:
            session.close()
        self.sessions = []
        if self._listener:
            self._listener.close()
            self._listener = None

    def running(self):
        return self._listener is not None

    def transfers(self):
        return [s.transfer for s in self.sessions if s.transfer and s.transfer.kind != "list"]

    def started(self, session):
        t = session.transfer
        if t.kind != "list":
            self.note(session.peer, ("sending " if t.kind == "send" else "receiving ") + t.name)

    def finished(self, session, transfer, complete):
        if transfer.kind == "receive":
            self.received += transfer.bytes
        else:
            self.sent += transfer.bytes
        if transfer.kind != "list":
            seconds = max(1, time.ticks_diff(time.ticks_ms(), transfer.started)) / 1000
            self.note(session.peer, "%s %s: %s, %s/s" % (
                ("got" if transfer.kind == "receive" else "sent") if complete else "stopped",
                transfer.name.rsplit("/", 1)[-1], size_text(transfer.bytes), size_text(int(transfer.bytes / seconds))))

    def poll(self, budget_ms=10):
        if not self._listener:
            return
        deadline = time.ticks_add(time.ticks_ms(), budget_ms)
        for _ in range(4):
            try:
                sock, address = self._listener.accept()
            except OSError:
                break
            peer = _peer_ip(address)
            if len(self.sessions) >= MAX_SESSIONS:
                try:
                    sock.send(b"421 Too many connections\r\n")
                except OSError:
                    pass
                sock.close()
                continue
            self.sessions.append(Session(self, sock, peer))
            self.note(peer, "connected")
        for session in self.sessions:
            session.poll()
        # The data, in turns, until the time of this tick is over.
        busy = [s for s in self.sessions if s.transfer]
        while busy and time.ticks_diff(deadline, time.ticks_ms()) > 0:
            moved = False
            share = time.ticks_add(time.ticks_ms(), max(1, budget_ms // len(busy)))
            if time.ticks_diff(share, deadline) > 0:
                share = deadline
            for s in busy:
                if s.step(share):
                    moved = True
            busy = [s for s in busy if s.transfer]
            if not moved:
                break
        self.sessions = [s for s in self.sessions if not s.closed]


def size_text(n):
    for unit in ("B", "KB", "MB", "GB"):
        if n < 1024 or unit == "GB":
            return ("%d %s" % (n, unit)) if unit == "B" else ("%.1f %s" % (n, unit))
        n /= 1024

# SPDX-License-Identifier: MIT
# FTP Server: the board's files (the whole SD card, or one folder of it) for a PC on the same
# network. The screen shows the addresses, the user and the password, who is connected, what moves
# and how fast, and the free space on the card. The password and the folder stay in settings.json,
# section "ftp": a client that saved them connects again after a restart.

import os
import time

import lvgl as lv

from ftp_server import Server, size_text

try:
    import mpy_settings

    HARDWARE = True
except ImportError:
    HARDWARE = False

PORT = 21
USER = "mpy"

_ui = None
_server = None
_log = []
_ticks = 0
_settings = {}
_folders = []  # (label, path)
_log_chars = 50  # what fits in the log, from its size
_log_lines = 9


def _clock():
    t = time.localtime()
    return "%02d:%02d" % (t[3], t[4])


def note(who, what):
    # Who, for the arrivals and the departures; the rest is short enough to read in one line.
    if what in ("connected", "logged in", "left", "disconnected", "wrong password") or who == "board":
        line = "%s  %s  %s" % (_clock(), who, what)
    else:
        line = "%s  %s" % (_clock(), what)
    _log.insert(0, line if len(line) <= _log_chars else line[:_log_chars - 3] + "...")
    del _log[_log_lines:]
    _ui.log.set_text("\n".join(_log))


def _new_password():
    return "%06d" % (int.from_bytes(os.urandom(4), "little") % 1000000)


def _save():
    if HARDWARE:
        try:
            mpy_settings.update("ftp", _settings)
        except OSError as error:
            note("board", "settings not saved: %s" % error)


def _addresses():
    if not HARDWARE:
        return [("USB", "192.168.7.1"), ("Wi-Fi", "192.168.1.50")]
    found = []
    for ip in _server.addresses():
        found.append(("USB" if ip.startswith("192.168.7.") else "Network", ip))
    return found


def _show_addresses():
    found = _addresses()
    port = "" if PORT == 21 else ":%d" % PORT
    _ui.addresses.set_text("\n".join("ftp://%s%s  %s" % (ip, port, name) for name, ip in found[:3])
                           or "No network: connect the Wi-Fi in Settings")


def _show_card():
    total, free = 3800 * 1024 * 1024, 3100 * 1024 * 1024  # the simulator: a made-up card
    if HARDWARE:
        try:
            st = os.statvfs(_server.root)
            total, free = st[0] * st[2], st[0] * st[4]
        except OSError:
            pass
    _ui.card.set_text("%s free of %s" % (size_text(free), size_text(total)))
    _ui.card_bar.set_value(100 - int(free * 100 // max(1, total)), False)


def _show_state():
    sessions = [s for s in _server.sessions if s.logged]
    if not HARDWARE:
        clients = "Connected: 192.168.1.20"
    elif not _server.running():
        clients = "Stopped"
    elif not sessions:
        clients = "No one connected"
    else:
        peers = sorted(set(s.peer for s in sessions))
        clients = "Connected: " + ", ".join(peers)
    _ui.clients.set_text(clients)
    transfers = _server.transfers()
    if transfers:
        t = transfers[0]
        seconds = max(1, time.ticks_diff(time.ticks_ms(), t.started)) / 1000
        verb = "Sending" if t.kind == "send" else "Receiving"
        _ui.transfer.set_text("%s %s\n%s, %s/s" % (verb, t.name.rsplit("/", 1)[-1],
                                                  size_text(t.bytes), size_text(int(t.bytes / seconds))))
        _ui.transfer_bar.set_value(int(t.bytes * 100 // t.size) if t.size else 0, False)
    else:
        _ui.transfer.set_text("No transfer")
        _ui.transfer_bar.set_value(0, False)
    _ui.totals.set_text("Received %s    Sent %s" % (size_text(_server.received), size_text(_server.sent)))


def tick():
    # Every 20 ms: the clients, with 10 ms for the data; twice a second the state; every 10 s
    # the addresses and the card.
    global _ticks
    _ticks += 1
    if _server.running():
        _server.poll(10)
    if _ticks % 25 == 0:
        _show_state()
    if _ticks % 500 == 0:
        _show_addresses()
        _show_card()


def _serve(on):
    if not HARDWARE:
        _ui.serve_label.set_text("Simulator")
        return
    try:
        if on:
            _server.start()
        else:
            _server.stop()
        _ui.serve_label.set_text("Serving" if on else "Stopped")
    except OSError as error:
        _ui.serve_label.set_text("Error %s" % error)
        _ui.serve_switch.remove_state(lv.STATE.CHECKED)
    _show_state()


def serve_changed(switch):
    _serve(switch.has_state(lv.STATE.CHECKED))


def new_password():
    _settings["password"] = _new_password()
    _server.password = _settings["password"]
    _ui.password.set_text(_settings["password"])
    _save()
    note("board", "new password")
    for session in _server.sessions:
        session.logged = False


def folder_changed(dropdown):
    index = dropdown.get_selected()
    if 0 <= index < len(_folders):
        _settings["root"] = _folders[index][1]
        _server.root = _settings["root"]
        for session in _server.sessions:
            session.cwd = "/"
        _save()
        note("board", "the clients now see " + _settings["root"])
        _show_card()


def start(ui):
    global _ui, _server, _settings, _folders, _log_chars, _log_lines
    _ui = ui
    ui.log.update_layout()
    _log_chars = max(20, ui.log.get_width() * 2 // 15)
    _log_lines = max(3, ui.log.get_height() // 17)
    lv.screen_active().set_style_bg_color(lv.color_hex(0x121820), 0)
    for bar in (ui.transfer_bar, ui.card_bar):
        bar.set_style_bg_opa(lv.OPA.COVER, 0)
    _settings = dict(mpy_settings.get("ftp", {}) if HARDWARE else {})
    if not _settings.get("password"):
        _settings["password"] = _new_password()
        _save()
    here = os.getcwd() if HARDWARE else "/usr/local/mpy/fs"
    _folders = [("The whole card", "/"), ("MicroPython files", here), ("Studio apps", "/lms_apps")]
    root = _settings.get("root") or "/"
    if root not in [f[1] for f in _folders]:
        _folders.append((root, root))
    ui.folder.set_options("\n".join("%s  %s" % f for f in _folders))
    ui.folder.set_selected([f[1] for f in _folders].index(root))
    _server = Server(root=root, user=USER, password=_settings["password"], port=PORT, note=note)
    ui.user.set_text(USER)
    ui.password.set_text(_settings["password"])
    _show_addresses()
    _show_card()
    if HARDWARE:
        note("board", "ready: FileZilla, WinSCP, a file manager")
        _serve(True)
    else:
        for who, what in (("192.168.1.20", "connected"), ("192.168.1.20", "logged in"),
                          ("192.168.1.20", "receiving /music/demo.mp3"),
                          ("192.168.1.20", "got demo.mp3: 4.2 MB, 3.1 MB/s")):
            note(who, what)
        ui.serve_label.set_text("Simulator")
    _show_state()
